<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lokasyonlar</title><style>
body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1100px;margin:32px auto;padding:0 18px}.panel{background:#fff;border:1px solid #e7ece8;border-radius:14px;padding:20px;margin:16px 0}.form-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}label{display:block;font-size:13px;font-weight:700}input,select{width:100%;box-sizing:border-box;margin-top:6px;padding:11px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}button{background:#176b50;color:#fff;border:0;border-radius:8px;padding:11px 16px;font-weight:700;cursor:pointer}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:560px}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf0ed;font-size:14px}.muted{color:#77847c;font-size:13px}.type{background:#eef5f0;padding:4px 8px;border-radius:20px;font-size:12px}@media(max-width:760px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.form-grid{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><h1>Lokasyon yönetimi</h1><p class="muted">Ülke, şehir, ilçe ve semtleri hiyerarşik olarak ekleyin. Alt konum eklemek için önce üst konumu seçin.</p>
<section class="panel"><h2>Yeni lokasyon ekle</h2><form method="post" action="<?= e(app_url('/admin/locations/save')) ?>"><?= csrf_field() ?><div class="form-grid">
<label>Konum türü<select name="location_type" id="locationType" required><option value="country">Ülke</option><option value="city">Şehir</option><option value="district">İlçe</option><option value="neighborhood">Semt / Mahalle</option></select></label>
<label>Üst konum<select name="parent_id" id="locationParent"><option value="0">Üst konum yok</option><?php foreach(($parents??[]) as $parent): ?><option value="<?= (int)$parent['id'] ?>" data-type="<?= e($parent['location_type']) ?>"><?= e($parent['full_name']) ?></option><?php endforeach; ?></select></label>
<label>Konum adı<input name="name" required maxlength="190" placeholder="Örn. Türkiye, Antalya, Kaş, Kalkan"></label>
<label>Sıralama<input type="number" name="sort_order" value="10"></label></div><p><button type="submit">Lokasyonu ekle</button></p></form></section>
<section class="panel"><h2>CSV ile toplu lokasyon aktarımı</h2><p class="muted">Tek dosyada ülke, şehir, ilçe ve semt/mahalle bilgilerini aktarabilirsiniz. Aynı üst konum altındaki mevcut kayıtlar tekrar oluşturulmaz.</p><p><a href="<?= e(app_url('/admin/locations/template')) ?>">Örnek CSV şablonunu indir</a></p><form method="post" action="<?= e(app_url('/admin/locations/import')) ?>" enctype="multipart/form-data"><?= csrf_field() ?><label>CSV dosyası<input type="file" name="locations_csv" accept=".csv,text/csv" required></label><p class="muted">UTF-8 CSV. Sütun başlıkları: country, city, district, neighborhood. Virgül, noktalı virgül veya sekme ayracı desteklenir. En fazla 5 MB ve 20.000 veri satırı.</p><button type="submit">CSV dosyasını içe aktar</button></form></section>
<?php if(!empty($importReport)): ?><section class="panel"><h2>Aktarım sonucu</h2><div class="form-grid"><div><strong><?= (int)$importReport['counts']['rows'] ?></strong><div class="muted">İşlenen satır</div></div><div><strong><?= (int)$importReport['counts']['inserted'] ?></strong><div class="muted">Yeni lokasyon</div></div><div><strong><?= (int)$importReport['counts']['existing'] ?></strong><div class="muted">Zaten mevcut</div></div><div><strong><?= (int)$importReport['counts']['errors'] ?></strong><div class="muted">Hatalı satır</div></div></div><?php if(!empty($importReport['errors'])): ?><h3>Satır hataları</h3><ul><?php foreach($importReport['errors'] as $error): ?><li>Satır <?= (int)$error['line'] ?>: <?= e($error['message']) ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
<section class="panel"><h2>Kayıtlı lokasyonlar</h2><div class="table-wrap"><table><thead><tr><th>Konum</th><th>Tür</th><th>Üst konum</th><th>Durum</th><th></th></tr></thead><tbody>
<?php foreach(($locations??[]) as $item): ?><tr><td><strong><?= e($item['name']) ?></strong></td><td><span class="type"><?= e(['country'=>'Ülke','city'=>'Şehir','district'=>'İlçe','neighborhood'=>'Semt / Mahalle'][$item['location_type']]??$item['location_type']) ?></span></td><td><?= e($item['parent_name']??'—') ?></td><td><?= (int)$item['is_active']?'Aktif':'Pasif' ?></td><td><form method="post" action="<?= e(app_url('/admin/locations/toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button type="submit"><?= (int)$item['is_active']?'Pasife al':'Aktifleştir' ?></button></form></td></tr><?php endforeach; ?>
<?php if(empty($locations)): ?><tr><td colspan="5">Henüz lokasyon eklenmemiş.</td></tr><?php endif; ?></tbody></table></div></section></main>
<script>
(function(){var type=document.getElementById('locationType'),parent=document.getElementById('locationParent');function update(){var t=type.value;Array.from(parent.options).forEach(function(o){if(!o.value)return;var allowed={city:['country'],district:['city'],neighborhood:['district']}[t]||[];o.hidden=allowed.indexOf(o.dataset.type)<0});parent.value='0';parent.disabled=t==='country';if(t==='country'){parent.value='0'}else if(parent.options.length>1){var first=Array.from(parent.options).find(function(o){return o.value&& !o.hidden});if(first)parent.value=first.value}}type.addEventListener('change',update);update()})();
</script></body></html>